```cpp
#include <iostream>
#include <cmath>

int main() {
    // Declare variables to store coordinates of the two points
    // Using double for better precision in calculations
    double x1, y1, x2, y2;

    // Prompt user for the first point's coordinates
    std::cout << "Enter the x and y coordinates for point 1: ";
    std::cin >> x1 >> y1;

    // Prompt user for the second point's coordinates
    std::cout << "Enter the x and y coordinates for point 2: ";
    std::cin >> x2 >> y2;

    // Calculate the Euclidean distance between the two points
    // The formula is derived from the Pythagorean theorem: a² + b² = c²
    // In 2D space, the distance formula is:
    // distance = √[(x2 - x1)² + (y2 - y1)²]
    //
    // Explanation:
    // 1. (x2 - x1) represents the horizontal distance (difference in x-coordinates)
    // 2. (y2 - y1) represents the vertical distance (difference in y-coordinates)
    // 3. Squaring these differences ensures we work with positive values
    // 4. Adding them together gives us the square of the hypotenuse
    // 5. Taking the square root gives us the actual distance (hypotenuse)

    double distance = std::sqrt(
        std::pow(x2 - x1, 2) + 
        std::pow(y2 - y1, 2)
    );

    // Output the calculated distance to the console
    std::cout << "The Euclidean distance between the two points is: " 
              << distance << std::endl;

    return 0;
}
