// Half Adder Module
// Performs addition of two single-bit binary inputs
// Outputs: Sum (XOR) and Carry (AND)

module half_adder (
    input  wire a,      // First operand
    input  wire b,      // Second operand
    output wire sum,    // Sum bit (a XOR b)
    output wire carry   // Carry bit (a AND b)
);

    // Half adder logic:
    // sum = a XOR b
    // carry = a AND b

    assign sum = a ^ b;
    assign carry = a & b;

endmodule

