int main() {
    // Declare variable to store the sum of even numbers
    int sumOfEvenNumbers = 0;

    // Declare loop variable to iterate from 1 to 100
    int number;

    // Loop through all numbers from 1 to 100 (inclusive)
    for (number = 1; number <= 100; number++) {
        // Check if the current number is even
        if (number % 2 == 0) {
            // If even, add it to the sum
            sumOfEvenNumbers += number;
        }
    }

    // Display the calculated result
    cout << "Sum of all even numbers between 1 to 100: " 
         << sumOfEvenNumbers << endl;

    return 0;  // End of the program
}
